const allowedOrigins = [
    'https://app.example.com',
    'https://admin.example.com'
];

app.use(cors({
    origin: (ctx) => {
        const origin = ctx.headers.origin;
        if (allowedOrigins.includes(origin)) {
            return origin;  // ✓
        }
        return false;  // 拒绝
    },
    credentials: true
}));

// 方法3: 子域名模式
app.use(cors({
    origin: (ctx) => {
        const origin = ctx.headers.origin;
        if (/^https:\/\/[a-z0-9-]+\.example\.com$/.test(origin)) {
            return origin;  // ✓ 允许子域名
        }
        return false;
    },
    credentials: true
}));
```

