## 错误处理和信息泄露

```javascript
// 危险配置
app.on('error', (err, ctx) => {
    console.error(err.stack);  // ❌ 仅记录
});

// 默认错误处理
app.use(async (ctx) => {
    throw new Error('Database connection failed: user=admin, pass=secret123');
    // ❌ Medium: 错误可能泄露到客户端
});

// 审计正则
throw new Error.*password|console\.error.*stack|ctx\.body.*err\.stack

// 安全修复
// 全局错误处理中间件
app.use(async (ctx, next) => {
    try {
        await next();
    } catch (err) {
        ctx.status = err.status || err.statusCode || 500;

        // 后端记录完整错误
        console.error({
            error: err.message,
            stack: err.stack,
            url: ctx.url,
            method: ctx.method,
            ip: ctx.ip,
            user: ctx.state.user?.id
        });

        // 生产环境隐藏详情
        if (process.env.NODE_ENV === 'production') {
            ctx.body = {
                error: 'An error occurred',
                code: err.code || 'INTERNAL_ERROR'
            };  // ✓
        } else {
            ctx.body = {
                error: err.message,
                stack: err.stack  // 仅开发环境
            };
        }

        // 触发应用级错误事件
        ctx.app.emit('error', err, ctx);
    }
});

// 日志脱敏
const logger = require('pino')();

app.use(async (ctx, next) => {
    const sanitized = { ...ctx.request.body };
    delete sanitized.password;
    delete sanitized.token;
    logger.info({ body: sanitized }, 'Request received');  // ✓
    await next();
});
```

