protected $except = [
    '*',                 // ❌ Critical: 全局禁用
    'api/*',             // ⚠️ API端点需其他保护
    '/webhook/*'         // ✓ 合理(外部回调)
];

// 审计正则
VerifyCsrfToken.*\$except|@csrf  # 检查是否正确使用

