## Fastify 特定漏洞

### 1. trustProxy 配置

```typescript
// 🔴 错误配置导致 IP 伪造
const app = Fastify({
  trustProxy: true  // 信任所有代理!
});

// 请求: X-Forwarded-For: 127.0.0.1
// request.ip 会是 127.0.0.1

// 🟢 安全: 指定信任的代理
const app = Fastify({
  trustProxy: ['127.0.0.1', '10.0.0.0/8']
});

// 搜索模式
trustProxy:\s*true(?!\s*,)
```

### 2. 路由安全

```typescript
// 🔴 路由顺序问题
fastify.get('/users/:id', getUser);
fastify.get('/users/me', getMe);  // 永远不会匹配!

// 🔴 通配符路由
fastify.get('/api/*', handler);  // 可能匹配过多

// 🟢 安全: 正确顺序
fastify.get('/users/me', getMe);
fastify.get('/users/:id', getUser);
```

### 3. 插件安全

```typescript
// 🔴 fastify-multipart 无限制
await fastify.register(multipart);

// 🟢 安全: 添加限制
await fastify.register(multipart, {
  limits: {
    fieldNameSize: 100,
    fieldSize: 1024 * 1024,  // 1MB
    fields: 10,
    fileSize: 5 * 1024 * 1024,  // 5MB
    files: 1,
    headerPairs: 50
  }
});

// 搜索模式
register\(multipart(?!.*limits)
```

### 4. 序列化安全

```typescript
// 🔴 无 schema 验证
fastify.post('/user', async (request) => {
  const user = request.body;  // 无验证!
  return db.createUser(user);
});

// 🟢 安全: 使用 JSON Schema
fastify.post('/user', {
  schema: {
    body: {
      type: 'object',
      required: ['name', 'email'],
      properties: {
        name: { type: 'string', maxLength: 50 },
        email: { type: 'string', format: 'email' }
      },
      additionalProperties: false  // 禁止额外字段
    }
  }
}, async (request) => {
  return db.createUser(request.body);
});

// 搜索模式
\.post\(.*async.*request(?!.*schema)
```

